<?php declare(strict_types=1); namespace Modules\PromptEngine\Services\ImageProviders; use Modules\PromptEngine\Interfaces\PlatformPromptProviderInterface; final class ChatGptImagePromptProvider extends AbstractPromptProvider implements PlatformPromptProviderInterface { public function platform():string{return 'chatgpt-image';} public function build(array $c):array{return ['prompt'=>$this->base($c).'Define distinct title, hero glyph, illustration, and information zones. Quality checklist: exact glyph, coherent visual metaphor, legible hierarchy, clean editable text zones. Do not include '.$this->avoid($c).'.','negative_prompt'=>'','recommended_settings'=>['quality'=>'high','aspect_ratio'=>$c['aspect_ratio']]];} }
